head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     Arıkan Optik · 2026 Gözlük Kataloğu
Author:   Optisyen Çağatay Gülümser
Version:  1.0.0
Design:   arikantime.com tasarım dili (Montserrat · beyaz/siyah · kırmızı vurgu)
----------------------------------------------- */
/* =====================================================================
   ARIKAN OPTİK — 2026 Gözlük Kataloğu · Blogger teması
   Tasarım dili: arikantime.com (Montserrat, beyaz/siyah bloklar, kırmızı vurgu)
   ===================================================================== */
:root{
  --ink:#111827; --ink-2:#374151; --muted:#919EA7; --muted-2:#6B7280;
  --red:#DC2626; --red-dark:#B91C1C; --line:#E5E7EB; --line-2:#F0F0F0;
  --bg:#FFFFFF; --bg-soft:#F3F4F6; --bg-warm:#F5F3EF; --black:#000000; --footer:#575756;
  --font:"Montserrat",system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  --wrap:1280px; --gutter:24px; --radius:4px;
  --shadow:0 10px 30px rgba(17,24,39,.08);
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;font-family:var(--font);font-size:15px;line-height:1.6;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
button{font:inherit;cursor:pointer}
h1,h2,h3,h4{margin:0;font-weight:500;line-height:1.2}
p{margin:0 0 1em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gutter)}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
#navbar,#navbar-iframe,.navbar{display:none!important;height:0!important;visibility:hidden}

/* ---- Tipografi öğeleri ------------------------------------------- */
.eyebrow{font-size:11px;letter-spacing:.32em;text-transform:uppercase;color:var(--red);font-weight:500;margin:0 0 14px}
.eyebrow--muted{color:var(--muted)}
.display{font-weight:300;text-transform:uppercase;letter-spacing:.12em;font-size:clamp(30px,4.6vw,56px);line-height:1.05}
.display strong{font-weight:600}
.title-2{font-weight:300;text-transform:uppercase;letter-spacing:.2em;font-size:clamp(20px,2.6vw,30px);color:var(--ink)}
.title-2.red{color:var(--red)}
.lead{color:var(--ink-2);font-weight:300;font-size:16px;max-width:60ch}
.link-arrow{display:inline-block;color:var(--red);font-size:12px;letter-spacing:.3em;text-transform:uppercase;font-weight:500;padding-bottom:6px;border-bottom:1px solid var(--red)}
.link-arrow:after{content:"\2192";margin-left:10px;letter-spacing:0}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:14px 26px;border-radius:var(--radius);font-size:12px;letter-spacing:.2em;text-transform:uppercase;font-weight:600;border:1px solid transparent;transition:.2s}
.btn--red{background:var(--red);color:#fff}.btn--red:hover{background:var(--red-dark)}
.btn--dark{background:var(--ink);color:#fff}.btn--dark:hover{background:#000}
.btn--ghost{background:transparent;color:var(--ink);border-color:var(--ink)}.btn--ghost:hover{background:var(--ink);color:#fff}
.btn--light{background:#fff;color:var(--ink);border-color:#fff}
.badge{display:inline-block;font-size:10px;letter-spacing:.18em;text-transform:uppercase;font-weight:600;padding:5px 9px;border-radius:2px;background:var(--bg-soft);color:var(--ink-2)}
.badge--red{background:var(--red);color:#fff}
.badge--dark{background:var(--ink);color:#fff}
.badge--line{background:transparent;border:1px solid var(--line);color:var(--ink-2)}

/* ---- Header -------------------------------------------------------- */
.site-header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.96);backdrop-filter:saturate(1.4) blur(8px);border-bottom:1px solid var(--line-2)}
.site-header__in{display:flex;align-items:center;gap:28px;height:72px}
.logo{display:flex;align-items:center;gap:10px;font-size:26px;font-weight:300;letter-spacing:.02em;color:var(--ink);white-space:nowrap}
.logo img{height:40px;width:auto}
.logo__img{height:42px!important;width:auto}
.logo--footer .logo__img{filter:brightness(0) invert(1);opacity:.9;height:36px!important}
.logo__mark{width:34px;height:34px;flex:none}
.logo__sub{font-size:10px;letter-spacing:.3em;text-transform:uppercase;color:var(--muted);margin-left:4px;font-weight:500}
.nav{display:flex;align-items:center;gap:4px;margin-left:auto}
.nav a,.nav summary{display:block;padding:10px 11px;font-size:13px;font-weight:500;color:var(--ink);letter-spacing:.01em;border-radius:var(--radius);list-style:none;cursor:pointer;white-space:nowrap}
.nav summary::-webkit-details-marker{display:none}
.nav a:hover,.nav summary:hover{color:var(--red)}
.nav details{position:relative}
.nav summary:after{content:"";display:inline-block;width:5px;height:5px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg);margin-left:8px;position:relative;top:-3px}
.nav .menu{position:absolute;top:100%;left:0;min-width:220px;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);padding:8px;border-radius:var(--radius);z-index:60}
.nav .menu a{padding:10px 12px;font-weight:500;display:flex;align-items:center;gap:10px}
.nav .menu a img{height:18px;width:auto;filter:grayscale(1);opacity:.8}
.nav .menu a:hover img{filter:none;opacity:1}
.nav .menu .sep{height:1px;background:var(--line);margin:6px 0}
.search{display:flex;align-items:center;border:1px solid var(--line);border-radius:999px;padding:4px 4px 4px 14px;gap:6px;background:#fff;min-width:230px}
.search input{border:0;outline:0;font:inherit;font-size:13px;width:100%;background:transparent;color:var(--ink)}
.search input::placeholder{color:var(--muted)}
.search button{border:0;background:var(--red);color:#fff;width:32px;height:32px;border-radius:50%;display:grid;place-items:center}
.search button svg{width:15px;height:15px}
.search-suggest{position:absolute;top:calc(100% + 6px);right:0;width:340px;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);border-radius:var(--radius);padding:6px;display:none;z-index:70;max-height:60vh;overflow:auto}
.search-suggest.open{display:block}
.search-suggest a{display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:var(--radius)}
.search-suggest a:hover{background:var(--bg-soft)}
.search-suggest img{width:64px;height:28px;object-fit:contain}
.search-suggest b{font-weight:600;font-size:13px}
.search-suggest small{color:var(--muted);font-size:11px;display:block}
.search-wrap{position:relative}
.burger{display:none;margin-left:auto;background:none;border:0;width:40px;height:40px;position:relative;flex:none}
.burger span,.burger span:before,.burger span:after{position:absolute;left:8px;width:24px;height:2px;background:var(--ink);content:"";transition:.2s}
.burger span{top:19px}.burger span:before{top:-7px;left:0}.burger span:after{top:7px;left:0}
@media (max-width:1024px){
  .site-header{backdrop-filter:none;-webkit-backdrop-filter:none;background:#fff}
  .burger{display:block}
  .logo{font-size:22px;min-width:0}
  .logo__sub{display:none}
  .logo__img{height:32px!important}
  .site-header__in{gap:12px}
  .nav{position:fixed;inset:72px 0 0 0;background:#fff;flex-direction:column;align-items:stretch;padding:16px var(--gutter);gap:0;display:none;overflow:auto;margin:0}
  .nav.open{display:flex}
  .nav a,.nav summary{padding:14px 0;border-bottom:1px solid var(--line-2);font-size:15px}
  .nav .menu{position:static;box-shadow:none;border:0;padding:0 0 8px 16px}
  .search{min-width:0;margin-top:12px}
  .site-header__in .search-wrap{display:none}
  .nav .search-wrap{display:block}
}
@media (min-width:1025px){.nav .search-wrap{display:none}}

/* ---- Hero ---------------------------------------------------------- */
.hero{background:var(--bg-soft);position:relative;overflow:hidden}
.hero__slides{position:relative;min-height:560px}
.hero__slide{position:absolute;inset:0;display:grid;grid-template-columns:1fr 1fr;min-height:560px;opacity:0;transition:opacity .7s;pointer-events:none}
.hero__slide.active{opacity:1;pointer-events:auto;position:relative}
.hero__text{display:flex;flex-direction:column;justify-content:center;padding:64px var(--gutter) 64px max(var(--gutter),calc((100vw - var(--wrap))/2 + var(--gutter)))}
.hero__text .display{margin-bottom:22px}
.hero__text .lead{margin-bottom:30px}
.hero__img{position:relative;min-height:420px}
.hero__img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 28%}
.hero__img:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--bg-soft) 0,rgba(243,244,246,0) 18%)}
.hero__arrow{position:absolute;top:50%;transform:translateY(-50%);width:46px;height:46px;border-radius:50%;background:var(--red);color:#fff;border:0;display:grid;place-items:center;z-index:5;box-shadow:0 6px 16px rgba(220,38,38,.35)}
.hero__arrow svg{width:18px;height:18px}
.hero__arrow--prev{left:22px}.hero__arrow--next{right:22px}
.hero__dots{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);display:flex;gap:8px;z-index:5}
.hero__dots button{width:9px;height:9px;border-radius:999px;border:0;background:rgba(17,24,39,.25);padding:0;transition:.2s}
.hero__dots button.active{background:var(--red);width:26px}
.hero-search{display:flex;max-width:460px;border:1px solid var(--ink);border-radius:var(--radius);overflow:hidden;background:#fff}
.hero-search input{flex:1;border:0;outline:0;font:inherit;padding:14px 16px;font-size:14px;min-width:0}
.hero-search button{border:0;background:var(--ink);color:#fff;padding:0 20px;font-size:11px;letter-spacing:.2em;text-transform:uppercase;font-weight:600}
.hero-search__hint{font-size:12px;color:var(--muted);margin-top:10px}
@media (max-width:860px){
  .hero__slide{grid-template-columns:1fr;min-height:0}
  .hero__img{min-height:320px;order:-1}
  .hero__img:after{background:linear-gradient(0deg,var(--bg-soft) 0,rgba(243,244,246,0) 22%)}
  .hero__text{padding:28px var(--gutter) 56px}
  .hero__arrow{display:none}
  .hero__slides{min-height:0}
}

/* ---- Logo şeridi & sayaçlar --------------------------------------- */
.logos{border-bottom:1px solid var(--line-2)}
.logos__in{display:grid;grid-template-columns:repeat(4,1fr);align-items:center;min-height:120px}
.logos__in a{display:grid;place-items:center;padding:22px 10px;filter:grayscale(1);opacity:.7;transition:.25s}
.logos__in a:hover{filter:none;opacity:1}
.logos__in img{max-height:56px;width:auto;max-width:160px}
@media (max-width:640px){.logos__in{grid-template-columns:repeat(2,1fr)}}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
.stats__item{position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;padding-top:46px;color:var(--ink);text-align:center;overflow:hidden}
.stats__item img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 20%;z-index:0}
.stats__item:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,#fff 0,#fff 36%,rgba(255,255,255,0) 72%);z-index:1}
.stats__item>*{position:relative;z-index:2}
.stats__num{font-size:56px;font-weight:300;color:var(--red);line-height:1}
.stats__label{font-size:11px;letter-spacing:.3em;text-transform:uppercase;margin-top:8px;font-weight:500}
@media (max-width:860px){.stats{grid-template-columns:repeat(2,1fr)}.stats__item{min-height:220px}}

/* ---- Bölümler ------------------------------------------------------ */
.section{padding:88px 0}
#page_body.section,.main.section{padding:0}
.section--soft{background:var(--bg-soft)}
.section--dark{background:var(--black);color:#fff}
.section--dark .title-2{color:#fff}
.section--dark .lead{color:#C9CDD2}
.section__head{text-align:center;margin-bottom:46px}
.section__head .lead{margin:14px auto 0}
.brand-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.brand-card{position:relative;aspect-ratio:3/4;overflow:hidden;background:#111;border-radius:var(--radius);display:block}
.brand-card img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 20%;transition:transform .8s}
.brand-card:hover img.bg{transform:scale(1.05)}
.brand-card:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0) 35%,rgba(0,0,0,.72) 100%)}
.brand-card__body{position:absolute;left:0;right:0;bottom:0;padding:26px;color:#fff;z-index:2}
.brand-card__name{font-size:22px;letter-spacing:.3em;text-transform:uppercase;font-weight:300}
.brand-card__count{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#D1D5DB;margin-top:6px}
.brand-card__logo{position:absolute;top:18px;left:18px;background:#fff;padding:8px 12px;border-radius:2px;z-index:2}
.brand-card__logo img{height:26px;width:auto}
@media (max-width:1024px){.brand-grid{grid-template-columns:repeat(2,1fr)}}
.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.split__item{position:relative;min-height:420px;overflow:hidden;border-radius:var(--radius);display:flex;align-items:flex-end;padding:36px;color:#fff;background:#222}
.split__item img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 40%;transition:transform .8s}
.split__item:hover img{transform:scale(1.04)}
.split__item:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.05) 30%,rgba(0,0,0,.75) 100%)}
.split__body{position:relative;z-index:2}
.split__body .eyebrow{color:#F3F4F6}
.split__body h3{font-size:34px;font-weight:300;letter-spacing:.2em;text-transform:uppercase;margin-bottom:10px}
.split__body p{color:#D1D5DB;max-width:44ch;font-weight:300}
.split__body .link-arrow{color:#fff;border-color:#fff}
@media (max-width:860px){.split{grid-template-columns:1fr}.split__item{min-height:320px}}
.guide-banner{display:grid;grid-template-columns:1.1fr .9fr;gap:60px;align-items:center}
.guide-banner svg{width:100%;height:auto}
.guide-banner dl{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:28px 0 0}
.guide-banner dt{font-size:36px;font-weight:300;color:var(--red)}
.guide-banner dd{margin:0;font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#C9CDD2}
@media (max-width:860px){.guide-banner{grid-template-columns:1fr;gap:30px}}

/* ---- Ürün kartları ------------------------------------------------- */
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
@media (max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}}
@media (max-width:760px){.grid{grid-template-columns:repeat(2,1fr);gap:12px}}
.card{background:#fff;border:1px solid var(--line-2);border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column;transition:.25s;position:relative}
.card:hover{box-shadow:var(--shadow);border-color:#fff;transform:translateY(-2px)}
.card__img{position:relative;aspect-ratio:4/3;display:grid;place-items:center;padding:14px;background:#fff}
.card__img img{width:100%;height:100%;object-fit:contain;transition:opacity .25s}
.card__img img.side{position:absolute;inset:14px;width:calc(100% - 28px);height:calc(100% - 28px);opacity:0}
.card:hover .card__img img.side{opacity:1}
.card:hover .card__img img.front{opacity:0}
.card__badges{position:absolute;top:10px;left:10px;display:flex;gap:6px;z-index:2}
.card__body{padding:14px 16px 16px;border-top:1px solid var(--line-2)}
.card__brand{font-size:10px;letter-spacing:.25em;text-transform:uppercase;color:var(--muted);font-weight:600}
.card__code{font-size:18px;font-weight:600;margin:4px 0 6px;letter-spacing:.02em}
.card__meta{font-size:12px;color:var(--ink-2);display:flex;justify-content:space-between;align-items:center;gap:8px}
.swatches{display:flex;gap:5px;flex-wrap:wrap}
.sw{width:14px;height:14px;border-radius:50%;border:1px solid rgba(0,0,0,.15);box-shadow:inset 0 0 0 1px rgba(255,255,255,.4)}
.sw--multi{background:conic-gradient(var(--c1) 0 50%,var(--c2) 50% 100%)}
.card__dims{font-size:11px;color:var(--muted);letter-spacing:.06em;margin-top:8px}

/* ---- Koleksiyon / filtre sayfası --------------------------------- */
.coll-head{padding:56px 0 34px;border-bottom:1px solid var(--line-2)}
.coll-head__in{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;flex-wrap:wrap}
.coll-head__logo img{height:54px;width:auto;margin-bottom:16px}
.coll-head .lead{margin-top:10px}
.coll-head__count{font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
.coll{display:grid;grid-template-columns:260px 1fr;gap:40px;padding:36px 0 90px}
.filters{position:sticky;top:90px;align-self:start;max-height:calc(100vh - 110px);overflow:auto;padding-right:6px}
.filters h4{font-size:11px;letter-spacing:.25em;text-transform:uppercase;color:var(--ink);margin:0 0 10px;font-weight:600}
.filters fieldset{border:0;padding:0;margin:0 0 26px}
.filters label{display:flex;align-items:center;gap:10px;font-size:13px;padding:5px 0;color:var(--ink-2);cursor:pointer}
.filters label span.n{margin-left:auto;color:var(--muted);font-size:11px}
.filters input[type=checkbox]{accent-color:var(--red);width:15px;height:15px}
.filters .sw{width:16px;height:16px}
.filters__clear{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--red);background:none;border:0;padding:0;font-weight:600}
.toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:22px;flex-wrap:wrap}
.toolbar select{font:inherit;font-size:13px;border:1px solid var(--line);border-radius:var(--radius);padding:9px 12px;background:#fff;color:var(--ink)}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chip{font-size:12px;border:1px solid var(--line);border-radius:999px;padding:6px 12px;background:#fff;color:var(--ink-2);display:inline-flex;gap:8px;align-items:center}
.chip b{font-weight:600;color:var(--ink)}
.chip button{border:0;background:none;color:var(--muted);padding:0;font-size:14px;line-height:1}
.filters-toggle{display:none}
.empty{padding:60px 20px;text-align:center;color:var(--muted)}
.empty b{display:block;color:var(--ink);font-size:18px;font-weight:500;margin-bottom:8px}
@media (max-width:900px){
  .coll{grid-template-columns:1fr;gap:20px}
  .filters{position:fixed;inset:0;background:#fff;z-index:80;padding:24px;max-height:none;display:none}
  .filters.open{display:block}
  .filters-toggle{display:inline-flex}
  .filters__close{position:absolute;top:14px;right:14px;border:0;background:var(--bg-soft);width:36px;height:36px;border-radius:50%;font-size:18px}
}
@media (min-width:901px){.filters__close{display:none}}

/* ---- Model (yazı) sayfası ----------------------------------------- */
.crumbs{font-size:12px;color:var(--muted);padding:18px 0 0;display:flex;gap:8px;flex-wrap:wrap}
.crumbs a:hover{color:var(--red)}
.crumbs span:not(:last-child):after{content:"/";margin-left:8px;color:var(--line)}
.model{padding:22px 0 60px}
.model__top{display:grid;grid-template-columns:1.15fr .85fr;gap:48px;align-items:start}
.model__gallery{position:sticky;top:92px}
.model__main{margin:0;background:#fff;border:1px solid var(--line-2);border-radius:var(--radius);aspect-ratio:4/3;display:grid;place-items:center;padding:30px;position:relative;overflow:hidden}
.model__main img{max-height:100%;width:100%;object-fit:contain;transition:opacity .2s}
.model__main .zoom{position:absolute;right:12px;bottom:12px;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
.model__thumbs{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px}
.model__thumbs figure{margin:0;border:1px solid var(--line-2);border-radius:var(--radius);aspect-ratio:3/2;display:grid;place-items:center;padding:12px;cursor:pointer;background:#fff;position:relative}
.model__thumbs figure.active{border-color:var(--ink)}
.model__thumbs figcaption{position:absolute;left:8px;top:6px;font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
.model__thumbs img{max-height:100%;object-fit:contain}
.model__brand{height:44px;width:auto;margin-bottom:18px}
.model__code{font-size:clamp(34px,4vw,48px);font-weight:600;letter-spacing:.02em;line-height:1}
.model__sub{color:var(--ink-2);margin:10px 0 14px;font-weight:300;font-size:15px}
.model__badges{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:26px}
.dims{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center;background:var(--bg-soft);border-radius:var(--radius);padding:18px}
.dims svg{width:100%;max-width:300px;height:auto}
.dims__nums{display:grid;grid-template-columns:repeat(3,auto);gap:16px;text-align:center}
.dims__nums b{display:block;font-size:22px;font-weight:500;color:var(--ink)}
.dims__nums small{font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
.dims__str{grid-column:1/-1;font-size:12px;color:var(--muted-2);margin:0}
.dims__str b{color:var(--ink);font-weight:600;letter-spacing:.1em}
.specs{width:100%;border-collapse:collapse;margin:24px 0;font-size:14px}
.specs th{text-align:left;font-weight:500;color:var(--muted-2);padding:10px 0;border-bottom:1px solid var(--line-2);width:42%;font-size:12px;letter-spacing:.12em;text-transform:uppercase}
.specs td{padding:10px 0;border-bottom:1px solid var(--line-2);font-weight:500}.specs td small{display:block;font-size:12px;margin-top:2px}
.colors h3{font-size:11px;letter-spacing:.25em;text-transform:uppercase;color:var(--ink);margin:0 0 12px;font-weight:600}
.colors h3 span{color:var(--muted);font-weight:500;margin-left:8px;letter-spacing:.05em;text-transform:none;font-size:12px}
.color-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px}
.color-btn{border:1px solid var(--line);background:#fff;border-radius:var(--radius);padding:8px;text-align:left;display:grid;gap:4px;transition:.2s}
.color-btn img{width:100%;aspect-ratio:3/1.15;object-fit:contain}
.color-btn b{font-size:12px;font-weight:600}
.color-btn small{font-size:11px;color:var(--muted-2);line-height:1.3}
.color-btn.active,.color-btn:hover{border-color:var(--ink)}
.color-btn.active{box-shadow:inset 0 0 0 1px var(--ink)}
.attrs{margin:22px 0 0;border:1px solid var(--line-2);border-radius:var(--radius);padding:16px 18px}
.attrs__title{font-size:11px;letter-spacing:.25em;text-transform:uppercase;font-weight:600;margin-bottom:10px;display:flex;justify-content:space-between}
.attrs__title b{color:var(--red)}
.attrs dl{margin:0;display:grid;grid-template-columns:1fr 1fr;gap:8px 16px}
.attrs dt{font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted)}
.attrs dd{margin:0;font-size:14px;font-weight:500;display:flex;align-items:center;gap:8px}
.cta{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px}
.cta--grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:28px}
.cta--grid .btn{width:100%;padding:15px 12px;font-size:11px;letter-spacing:.14em;gap:9px;white-space:nowrap;margin:0}
.cta--grid .btn svg{width:17px;height:17px;flex:none;fill:currentColor}
.cta--grid .cta__main{grid-column:1/-1;padding:17px 20px;font-size:12px;letter-spacing:.2em}
.cta--grid .btn--ghost{border-color:#D1D5DB;color:var(--ink)}
.cta--grid .btn--ghost:hover{background:var(--ink);border-color:var(--ink);color:#fff}
.cta--grid .fav--text{padding:15px 12px}.cta--grid .fav--text svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:2}
.cta--grid .fav--text.on{color:var(--red);border-color:var(--red)}.cta--grid .fav--text.on svg{fill:var(--red)}.cta--grid .fav--text.on:hover{background:var(--red);color:#fff}.cta--grid .fav--text.on:hover svg{fill:#fff}
@media (max-width:640px){.cta--grid{grid-template-columns:1fr}}
.share{margin-top:18px;font-size:12px;color:var(--muted);display:flex;gap:14px;align-items:center}
.share a{color:var(--ink-2);text-decoration:underline;text-underline-offset:3px}
.share a:hover{color:var(--red)}
@media (max-width:960px){.model__top{grid-template-columns:1fr;gap:28px}.model__gallery{position:static}}
@media (max-width:600px){.dims{grid-template-columns:1fr}.dims svg{max-width:260px;margin:0 auto}.dims__nums{justify-content:center}}
.variants{padding:60px 0;border-top:1px solid var(--line-2)}
.variants .section__head{margin-bottom:30px}
.variant-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
@media (max-width:1000px){.variant-grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:600px){.variant-grid{grid-template-columns:1fr}}
.variant{border:1px solid var(--line-2);border-radius:var(--radius);padding:16px;background:#fff}
.variant__imgs{display:grid;gap:8px}
.variant__imgs img{width:100%;aspect-ratio:3/1.1;object-fit:contain;background:#fff;border:1px solid var(--line-2);border-radius:2px;padding:6px}
.variant__code{font-weight:600;font-size:15px;margin:12px 0 8px;display:flex;justify-content:space-between;align-items:center}
.variant dl{margin:0;display:grid;grid-template-columns:1fr;gap:6px}
.variant dt{font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted)}
.variant dd{margin:0 0 4px;font-size:13px;font-weight:500}
.guide-mini{background:var(--bg-soft);border-radius:var(--radius);padding:28px;display:grid;grid-template-columns:auto 1fr;gap:26px;align-items:center;margin:0 0 50px}
.guide-mini svg{width:220px;height:auto}
.guide-mini h3{font-size:13px;letter-spacing:.25em;text-transform:uppercase;font-weight:600;margin-bottom:8px}
.guide-mini p{font-size:14px;color:var(--ink-2);margin:0 0 10px}
@media (max-width:700px){.guide-mini{grid-template-columns:1fr}.guide-mini svg{width:100%}}
.faq details{border-bottom:1px solid var(--line-2)}
.faq summary{list-style:none;cursor:pointer;padding:16px 0;font-weight:500;font-size:15px;display:flex;justify-content:space-between;gap:14px}
.faq summary::-webkit-details-marker{display:none}
.faq summary:after{content:"+";color:var(--red);font-weight:300;font-size:22px;line-height:1}
.faq details[open] summary:after{content:"\2212"}
.faq p{color:var(--ink-2);font-size:14px;padding-bottom:16px;margin:0;max-width:75ch}
.related{padding:60px 0 90px;background:var(--bg-soft)}
.related .section__head{margin-bottom:28px}
.lightbox{position:fixed;inset:0;background:rgba(255,255,255,.96);z-index:100;display:none;place-items:center;padding:30px;cursor:zoom-out}
.lightbox.open{display:grid}
.lightbox img{max-width:min(1200px,96vw);max-height:90vh;object-fit:contain}

/* ---- Statik sayfalar ---------------------------------------------- */
.page{padding:60px 0 90px}
.page__in{max-width:820px;margin:0 auto}
.page__in:has(.dealers-app){max-width:1100px}
.page h1{font-weight:300;text-transform:uppercase;letter-spacing:.15em;font-size:clamp(26px,3.4vw,40px);margin-bottom:28px}
.page h2{font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--red);font-weight:600;margin:40px 0 12px}
.page h3{font-size:17px;font-weight:600;margin:24px 0 8px}
.page p,.page li{color:var(--ink-2);font-size:15px;line-height:1.75}
.page ul{padding-left:20px}
.page table{width:100%;border-collapse:collapse;font-size:14px;margin:16px 0}
.page th,.page td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line)}
.page th{font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted-2);font-weight:600}
.page .note{background:var(--bg-soft);border-left:3px solid var(--red);padding:16px 18px;border-radius:0 var(--radius) var(--radius) 0;margin:20px 0}
.page figure{margin:24px 0}
.page figure svg{width:100%;max-width:560px;height:auto}
.page .dealers{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px;list-style:none;padding:0}
.page .dealers li{border:1px solid var(--line);border-radius:var(--radius);padding:16px}
.page .dealers b{display:block;font-weight:600;color:var(--ink);margin-bottom:4px}

/* ---- Footer -------------------------------------------------------- */
.site-footer{background:var(--footer);color:#D9D9D9;margin-top:0}
.site-footer__in{display:grid;grid-template-columns:1.4fr repeat(4,1fr);gap:30px;padding:60px 0 40px}
.site-footer .logo{color:#fff;margin-bottom:18px}
.site-footer .logo__sub{color:#BDBDBD}
.site-footer h4{color:#fff;font-size:12px;letter-spacing:.2em;text-transform:uppercase;font-weight:600;margin:0 0 16px}
.site-footer a{display:block;font-size:13px;color:#C8C8C8;padding:5px 0;font-weight:300}
.site-footer a:hover{color:#fff}
.site-footer p{font-size:13px;font-weight:300;color:#C8C8C8;max-width:36ch}
.social{display:flex;gap:12px;margin-top:8px}
.social a{width:34px;height:34px;border:1px solid #7a7a79;border-radius:50%;display:grid;place-items:center;padding:0}
.social svg{width:16px;height:16px;fill:#fff}
.site-footer__bottom{border-top:1px solid #6b6b6a;padding:18px 0;font-size:12px;color:#BDBDBD;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media (max-width:900px){.site-footer__in{grid-template-columns:1fr 1fr}}
@media (max-width:520px){.site-footer__in{grid-template-columns:1fr}}
.to-top{position:fixed;right:22px;bottom:22px;width:44px;height:44px;border-radius:50%;background:var(--red);color:#fff;border:0;display:grid;place-items:center;z-index:40;opacity:0;pointer-events:none;transition:.3s;box-shadow:0 6px 16px rgba(220,38,38,.35)}
.to-top.show{opacity:1;pointer-events:auto}
.wa-fab{position:fixed;right:18px;bottom:78px;width:52px;height:52px;border-radius:50%;background:#25D366;display:grid;place-items:center;z-index:40;box-shadow:0 6px 16px rgba(0,0,0,.2)}
.wa-fab svg{width:28px;height:28px;fill:#fff}
.skeleton{min-height:300px;display:grid;place-items:center;color:var(--muted);font-size:12px;letter-spacing:.3em;text-transform:uppercase}
.blogger-posts{display:none}
.post-body-fallback{padding:40px 0}

.footer-abuse{display:none}.footer-abuse .widget{margin:0}.footer-abuse a{display:inline;font-size:11px;color:#9a9a9a;text-decoration:underline}

/* ---- Yetkili satış noktaları haritası ---- */
.dealers-app .lead{margin-bottom:22px}
.dealers-search{position:relative;display:flex;gap:8px;max-width:520px;margin:0 0 26px}
.dealers-search input{flex:1;font:inherit;font-size:14px;padding:13px 16px;border:1px solid var(--ink);border-radius:var(--radius);outline:0;min-width:0}
.dealers-suggest{position:absolute;top:calc(100% + 6px);left:0;right:0;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);border-radius:var(--radius);padding:6px;display:none;z-index:30}
.dealers-suggest.open{display:block}
.dealers-suggest button{display:flex;justify-content:space-between;align-items:center;width:100%;border:0;background:none;text-align:left;padding:9px 10px;border-radius:var(--radius);font:inherit}
.dealers-suggest button:hover{background:var(--bg-soft)}
.dealers-suggest b{font-weight:600;font-size:14px}.dealers-suggest small{color:var(--muted);font-size:11px}
.dealers-map{position:relative;background:var(--bg-soft);border-radius:var(--radius);padding:14px}
.dealers-map svg{width:100%;height:auto;display:block}
.dealers-map path.prov{fill:#E5E7EB;stroke:#fff;stroke-width:1.2;cursor:pointer;transition:fill .15s}
.dealers-map path.prov:hover{fill:#9CA3AF}
.dealers-map path.prov.has{fill:#DC2626}
.dealers-map path.prov.has:hover{fill:#B91C1C}
.dealers-map path.prov.active{fill:#111827!important;stroke:#111827}
.dealers-tip{position:absolute;display:none;pointer-events:none;background:#111827;color:#fff;font-size:12px;padding:6px 10px;border-radius:4px;white-space:nowrap;z-index:5}
.dealers-legend{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;color:var(--muted-2);margin:12px 0 36px}
.dealers-legend span{display:inline-flex;align-items:center;gap:8px}
.dealers-head{margin-bottom:20px}.dealers-head .title-2{margin:4px 0 6px}
.dealer-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}
.dealer{border:1px solid var(--line);border-radius:var(--radius);padding:18px;display:flex;flex-direction:column;gap:6px}
.dealer__name{font-weight:600;font-size:17px}
.dealer__district{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--red);font-weight:600}
.dealer__row{font-size:14px;color:var(--ink-2)}
.dealer__hours{color:var(--muted-2);font-size:13px}
.dealer__brands{display:flex;gap:6px;flex-wrap:wrap;margin-top:4px}
.dealer__actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.dealer__actions .btn{padding:10px 14px;font-size:11px}
.dealer-empty{font-size:15px;color:var(--ink-2)}
.dealer-empty a{color:var(--red);text-decoration:underline}
.page .dealers-app .page__in{max-width:none}

/* ---- Blog ---- */
.blog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
@media (max-width:900px){.blog-grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:600px){.blog-grid{grid-template-columns:1fr}}
.bcard{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line-2);border-radius:var(--radius);overflow:hidden;transition:.25s}
.bcard:hover{box-shadow:var(--shadow);transform:translateY(-2px)}
.bcard__img{aspect-ratio:16/10;overflow:hidden;background:var(--bg-soft)}
.bcard__img img{width:100%;height:100%;object-fit:cover;transition:transform .6s}
.bcard:hover .bcard__img img{transform:scale(1.04)}
.bcard__body{padding:18px 20px 22px}
.bcard__date{font-size:10px;letter-spacing:.25em;text-transform:uppercase;color:var(--red);font-weight:600;margin-bottom:8px}
.bcard__title{font-size:18px;font-weight:600;line-height:1.3;margin-bottom:8px}
.bcard__sum{font-size:13px;color:var(--ink-2);line-height:1.6}
.blog-list{padding:36px 0 90px}
.article{padding:10px 0 60px}
.article__in{max-width:820px;margin:0 auto}
.article__date{margin:26px 0 10px}
.article__title{font-weight:600;font-size:clamp(28px,3.6vw,44px);line-height:1.15;margin-bottom:26px;letter-spacing:-.01em}
.article__cover{margin:0 0 30px;border-radius:var(--radius);overflow:hidden;background:var(--bg-soft)}
.article__cover img{width:100%;max-height:520px;object-fit:cover}
.article__body{font-size:16px;line-height:1.8;color:var(--ink-2)}
.article__body .article__lead{font-size:19px;color:var(--ink);font-weight:300;line-height:1.6}
.article__body h2{font-size:22px;font-weight:600;color:var(--ink);margin:36px 0 12px}
.article__body h3{font-size:17px;font-weight:600;color:var(--ink);margin:26px 0 8px}
.article__body p{margin:0 0 16px}
.article__body ul,.article__body ol{padding-left:22px;margin:0 0 18px}
.article__body li{margin-bottom:6px}
.article__body table{width:100%;border-collapse:collapse;font-size:14px;margin:16px 0 24px}
.article__body th,.article__body td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line)}
.article__body th{font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted-2);font-weight:600}
.article__body a{color:var(--red);text-decoration:underline;text-underline-offset:3px}
.article__body a.link-arrow{text-decoration:none}
.article__body img{border-radius:var(--radius)}
.article__tip{background:var(--bg-soft);border-left:3px solid var(--red);padding:16px 18px;border-radius:0 var(--radius) var(--radius) 0;margin:24px 0}
.article__labels{display:flex;gap:8px;flex-wrap:wrap;margin-top:30px}

/* ---- Karşılaştırma kaydırıcısı (clip-on / optik) ---- */
.cmp{position:relative;user-select:none;-webkit-user-select:none;touch-action:none;background:#F3F4F6;border-radius:var(--radius);overflow:hidden;cursor:ew-resize}
.cmp__stage{position:relative;width:100%}
.cmp__stage img{display:block;width:100%;height:auto;pointer-events:none}
.cmp__right{position:absolute;inset:0;clip-path:inset(0 0 0 50%)}
.cmp__bar{position:absolute;top:0;bottom:0;left:50%;width:2px;background:#fff;transform:translateX(-1px);box-shadow:0 0 0 1px rgba(0,0,0,.06)}
.cmp__handle{position:absolute;top:50%;left:50%;width:52px;height:52px;border-radius:50%;background:#fff;box-shadow:0 6px 18px rgba(17,24,39,.18);transform:translate(-50%,-50%);display:grid;place-items:center;color:var(--ink);font-size:18px;letter-spacing:2px;font-weight:300}
.cmp__handle:after{content:"\2039\00a0\203A"}
.cmp__labels{display:flex;justify-content:space-between;gap:20px;padding:22px 4px 0}
.cmp__label{font-size:12px;letter-spacing:.3em;text-transform:uppercase;font-weight:600;color:var(--ink)}
.cmp__label small{display:block;font-size:11px;letter-spacing:.05em;text-transform:none;font-weight:400;color:var(--muted-2);margin-top:4px}
.cmp__label--r{text-align:right}
.cmp-wrap{max-width:900px;margin:0 auto}
.cmp-title{text-align:center;font-weight:300;letter-spacing:.3em;text-transform:uppercase;font-size:clamp(18px,2.4vw,28px);margin-bottom:28px}

/* ---- Gözlük Asistanı ---------------------------------------------- */
.ast-launch{position:fixed;left:18px;bottom:18px;width:236px;background:#fff;border-radius:6px;box-shadow:0 14px 40px rgba(17,24,39,.22);z-index:45;overflow:hidden;transform:translateY(24px);opacity:0;transition:.45s cubic-bezier(.2,.8,.2,1);font-family:var(--font)}
.ast-launch.in{transform:none;opacity:1}
.ast-launch.min{display:none}
.ast-launch__head{background:var(--ink);color:#fff;font-size:12px;letter-spacing:.22em;text-transform:uppercase;font-weight:600;padding:12px 40px 12px 16px}
.ast-launch__x{position:absolute;top:6px;right:6px;width:28px;height:28px;border:0;background:transparent;color:#fff;font-size:13px;line-height:1;border-radius:50%}
.ast-launch__x:hover{background:rgba(255,255,255,.15)}
.ast-launch__img{height:120px;background-size:cover;background-position:50% 30%;position:relative;display:flex;align-items:flex-end;padding:14px}
.ast-launch__img:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0) 20%,rgba(0,0,0,.72))}
.ast-launch__img span{position:relative;color:#fff;font-weight:600;font-size:16px;line-height:1.2}
.ast-launch__cta-s{display:none}
.ast-launch__cta{display:block;width:100%;border:0;background:var(--red);color:#fff;padding:13px;font-size:12px;letter-spacing:.2em;text-transform:uppercase;font-weight:600}
.ast-launch__cta:hover{background:var(--red-dark)}
.ast-tab{position:fixed;left:0;bottom:120px;z-index:45;border:0;background:var(--red);color:#fff;padding:14px 12px;font-size:11px;letter-spacing:.24em;text-transform:uppercase;font-weight:600;writing-mode:vertical-rl;transform:rotate(180deg) translateX(-100%);border-radius:0 4px 4px 0;box-shadow:0 6px 16px rgba(220,38,38,.35);display:none;transition:.4s}
.ast-tab.in{transform:rotate(180deg)}
.ast-tab.show{display:block}
.ast-tab:hover{background:var(--red-dark)}
body.ast-open{overflow:hidden}
.ast{position:fixed;inset:0;z-index:100;background:rgba(17,24,39,.6);backdrop-filter:blur(4px);display:none;align-items:center;justify-content:center;padding:24px}
.ast.open{display:flex}
.ast__box{position:relative;width:min(1120px,100%);height:min(720px,100%);background:#fff;border-radius:10px;overflow:hidden;display:grid;grid-template-columns:1fr 1.05fr;box-shadow:0 30px 80px rgba(0,0,0,.4);animation:astIn .35s cubic-bezier(.2,.8,.2,1)}
@keyframes astIn{from{transform:translateY(24px) scale(.98);opacity:0}to{transform:none;opacity:1}}
.ast__x{position:absolute;top:14px;right:14px;z-index:3;width:40px;height:40px;border:0;background:transparent;color:var(--muted-2);font-size:18px;border-radius:50%}
.ast__x:hover{background:var(--bg-soft);color:var(--ink)}
.ast__media{background:var(--bg-soft);overflow:hidden;position:relative}
.ast.wide .ast__box{grid-template-columns:1fr}.ast.wide .ast__media{display:none}
.ast__media img{width:100%;height:100%;object-fit:cover;object-position:50% 30%;transition:opacity .3s}
.ast__media--model{background:#fff;display:grid;place-items:center;padding:40px}
.ast__media--model img{object-fit:contain;width:auto;height:auto;max-width:100%;max-height:70%;padding:0}
.ast__panel{padding:52px 48px 28px;overflow:auto;display:flex;flex-direction:column}
.ast__head{margin-bottom:18px}
.ast__title{font-size:clamp(22px,2.4vw,30px);font-weight:600;line-height:1.2;letter-spacing:-.01em;margin:0 0 10px}
.ast__sub{color:var(--muted-2);font-size:14px;line-height:1.7;margin:0}
.ast__bar{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:10px 0;margin-bottom:16px;font-size:14px;color:var(--ink-2)}
.ast__bar .btn{padding:10px 22px}
.ast__bar .btn:disabled{background:var(--bg-soft);color:var(--muted);cursor:default}
.ast__body{flex:1}
.ast-grid{display:grid;gap:14px}
.ast-grid--3{grid-template-columns:repeat(3,1fr)}
.ast-grid--4{grid-template-columns:repeat(4,1fr)}
.ast-grid--sw{grid-template-columns:repeat(4,1fr)}
.ast-opt{display:flex;flex-direction:column;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:6px;padding:14px 10px 12px;color:var(--ink);transition:.15s;text-align:center}
.ast-opt:hover{border-color:var(--ink);transform:translateY(-2px);box-shadow:var(--shadow)}
.ast-opt.on{border-color:var(--red);box-shadow:0 0 0 2px var(--red) inset}
.ast-opt__ico{width:100%;height:68px;display:grid;place-items:center;color:var(--ink)}
.ast-opt__ico svg{width:100%;max-width:120px;height:68px}
.ast-opt__ico img{max-height:68px;width:auto;object-fit:contain}
.ast-opt__q{font-size:34px;font-weight:300;color:var(--muted)}
.ast-opt__l{font-size:13px;font-weight:500}
.ast-sw{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,var(--c1) 50%,var(--c2) 50%);box-shadow:inset 0 0 0 1px rgba(0,0,0,.12)}
.ast-sw--any{background:conic-gradient(#DC2626,#FACC15,#166534,#2563EB,#7C3AED,#DC2626)}
.ast-grid--sw .ast-opt__ico{height:52px}
.ast-list{display:flex;flex-direction:column;gap:10px;max-width:360px}
.ast-opt--row{flex-direction:row;justify-content:flex-start;padding:16px 20px;font-size:15px;font-weight:500}
.ast__foot{display:flex;align-items:center;gap:20px;margin-top:22px;padding-top:8px}
.ast__back{border:0;background:#FEE2E2;color:var(--red);padding:10px 16px;border-radius:999px;font-size:13px;font-weight:600}
.ast__back:hover{background:#FECACA}
.ast__prog{flex:1;height:5px;background:var(--line);border-radius:3px;overflow:hidden}
.ast__prog i{display:block;height:100%;background:var(--red);width:0;transition:width .5s}
.ast__loading{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.ast__loading p{font-size:clamp(20px,2.4vw,28px);font-weight:600;color:var(--red);margin-bottom:22px}
.ast__prog--big{width:min(420px,100%);height:10px;border-radius:6px}
.ast__prog--big i{transition:width 1.4s ease-in-out}
.ast__rhead{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px;padding-right:44px}
.ast__rtitle{text-align:center}.ast__rtitle .eyebrow{margin:0 0 8px;color:var(--muted-2)}
.ast__dots{display:flex;gap:6px;justify-content:center}
.ast__dots i{width:8px;height:8px;border-radius:50%;background:var(--line)}
.ast__dots i.on{background:var(--red)}
.ast__arrow{width:44px;height:44px;border-radius:50%;border:1px solid var(--line);background:#fff;font-size:26px;line-height:1;color:var(--ink);display:grid;place-items:center}
.ast__arrow:disabled{opacity:.3;cursor:default}
.ast__res{flex:1}
.ast__meta{color:var(--muted-2);font-size:14px;margin:0 0 18px}
.ast__pct{display:inline-block;background:var(--ink);color:#fff;font-size:11px;letter-spacing:.1em;font-weight:600;padding:4px 9px;border-radius:999px;margin-left:8px;vertical-align:middle}
.ast__cta{width:100%;padding:16px;margin-bottom:18px}
.ast__why{display:flex;gap:14px;border:1px solid var(--line);border-radius:8px;padding:16px 18px;margin-bottom:18px;background:#FAFAFA}
.ast__why svg{width:22px;height:22px;flex:none;color:var(--red);margin-top:2px}
.ast__why p{margin:0;font-size:14px;line-height:1.7;color:var(--ink-2)}
.ast__chips{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 18px;font-size:13px;color:var(--ink-2)}
.ast__chips li{display:flex;align-items:center;gap:7px}
.ast__chips b{font-weight:600;color:var(--ink)}
.ast__chips i{width:18px;height:18px;border-radius:50%;background:var(--ink);flex:none;position:relative}
.ast__chips i:after{content:"";position:absolute;left:6px;top:3px;width:4px;height:8px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
.ast__chips li.no i{background:var(--line)}
.ast__chips li.no i:after{border-color:var(--muted-2);width:7px;height:0;border-width:0 0 2px 0;transform:none;left:5px;top:7px}
.ast__chips li.no{color:var(--muted-2)}
.ast__tools{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}
.ast__tools button{border:0;background:#FEE2E2;color:var(--red);padding:11px 16px;border-radius:999px;font-size:13px;font-weight:600}
.ast__tools button:hover{background:#FECACA}
.ast__table{overflow:auto;flex:1}
.ast__table table{border-collapse:collapse;width:100%;font-size:13px}
.ast__table th{text-align:left;color:var(--muted-2);font-weight:500;padding:8px 10px 8px 0;white-space:nowrap;border-bottom:1px solid var(--line-2);vertical-align:middle}
.ast__table td{padding:8px 10px;border-bottom:1px solid var(--line-2);vertical-align:middle;min-width:120px}
.ast__table img{width:110px;height:auto}
.ast__table small{display:block;color:var(--muted-2)}
.ast__table .btn{padding:9px 14px;font-size:11px}
.ast-band{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:40px}
.ast-band__img{min-height:360px;background-size:cover;background-position:50% 30%;border-radius:6px}
.ast-band__steps{display:flex;gap:18px;flex-wrap:wrap;margin:22px 0 28px;padding:0;list-style:none}
.ast-band__steps li{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2);display:flex;align-items:center;gap:8px}
.ast-band__steps li:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--red)}
@media (max-width:900px){
  .ast{padding:0}
  .ast__box{grid-template-columns:1fr;grid-template-rows:160px 1fr;height:100%;border-radius:0}
  .ast__media--model{padding:14px 44px 10px 14px}.ast__media--model img{max-height:100%}
  .ast__x{background:rgba(255,255,255,.9);box-shadow:0 2px 8px rgba(0,0,0,.15);color:var(--ink);width:34px;height:34px;top:10px;right:10px}
  .ast__panel{padding:22px 18px 18px}
  .ast-grid--3,.ast-grid--4,.ast-grid--sw{grid-template-columns:repeat(3,1fr)}
  .ast-grid{gap:10px}.ast-opt{padding:10px 6px}.ast-opt__ico{height:54px}.ast-opt__ico svg,.ast-opt__ico img{max-height:54px;height:54px}
  .ast__rhead{padding-right:0}
  .ast-band{grid-template-columns:1fr}.ast-band__img{min-height:220px}
  .ast-launch{width:200px;left:12px;bottom:12px}.ast-launch__img{height:96px}
}
@media (max-width:480px){.ast-grid--sw{grid-template-columns:repeat(3,1fr)}.ast__title{font-size:20px}}
@media (max-width:640px){
  .ast-launch{width:auto;left:12px;bottom:14px;border-radius:999px;background:var(--red);display:flex;align-items:center;box-shadow:0 8px 24px rgba(17,24,39,.25)}
  .ast-launch__head,.ast-launch__img,.ast-launch__cta-l{display:none}
  .ast-launch__cta-s{display:inline}
  .ast-launch__cta{width:auto;padding:11px 6px 11px 16px;font-size:11px;letter-spacing:.14em}
  .ast-launch__cta-s:after{content:"\203A";margin-left:8px;font-size:15px;letter-spacing:0}
  .ast-launch__x{position:static;width:32px;height:32px;margin-right:4px;color:#fff;font-size:12px}
}

/* ---- QR etiket üretici ----------------------------------------------- */
.qr-bar{display:flex;flex-wrap:wrap;gap:14px 28px;align-items:center;border:1px solid var(--line);border-radius:var(--radius);padding:14px 18px;margin:0 0 14px}
.qr-bar__g{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.qr-bar__g>span{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);margin-right:4px}
.qr-bar__act{margin-left:auto}.qr-bar__act .btn{padding:10px 16px}
.qr-n{display:inline-block;background:#fff;color:var(--red);border-radius:999px;padding:0 7px;margin-left:6px;font-size:11px}
.chip{border:1px solid var(--line);background:#fff;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:500;color:var(--ink-2)}
.chip.on{background:var(--ink);color:#fff;border-color:var(--ink)}
.qr-hint{font-size:13px;color:var(--muted-2);margin:0 0 18px}
.qr-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px}
.qrl{position:relative;display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;border:1px solid var(--line);border-radius:4px;padding:10px 12px 14px;background:#fff;cursor:pointer;transition:.15s}
.qrl:hover{border-color:var(--ink)}
.qrl.on{border-color:var(--red);box-shadow:0 0 0 2px var(--red) inset}
.qrl__check{position:absolute;top:8px;right:8px;width:18px;height:18px;border:1.5px solid var(--line);border-radius:50%;background:#fff}
.qrl.on .qrl__check{background:var(--red);border-color:var(--red)}
.qrl.on .qrl__check:after{content:"";position:absolute;left:6px;top:3px;width:4px;height:8px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
.qrl__l{min-width:0}
.qrl__l img{height:16px;width:auto;margin-bottom:8px}
.qrl__l b{display:block;font-size:20px;font-weight:600;letter-spacing:.02em;line-height:1}
.qrl__l small{display:block;font-size:10px;color:var(--muted-2);margin-top:5px}
.qrl__l em{display:block;font-style:normal;font-size:9px;color:var(--ink-2);margin-top:6px;letter-spacing:.04em}
.qrl__q{width:76px;height:76px}.qrl__q svg{width:100%;height:100%;display:block}
.qrl__site{position:absolute;left:12px;bottom:4px;font-size:8px;color:var(--muted);letter-spacing:.06em}
.qr-print{display:none}
@media print{
  body>*:not(#qr-print){display:none!important}
  body{background:#fff}
  @page{size:A4;margin:0}
  .qr-print{display:block}
  .qr-page{width:210mm;height:297mm;box-sizing:border-box;padding:13.5mm 5mm;display:grid;grid-template-columns:repeat(4,50mm);grid-auto-rows:30mm;page-break-after:always;break-after:page}
  .qr-print--l .qr-page{padding:22.5mm 0 0 0;grid-template-columns:repeat(3,70mm);grid-auto-rows:42mm}
  .qr-print .qrl{border:.2mm dashed #bbb;border-radius:0;padding:2mm 2.5mm 4mm;gap:1.5mm;box-shadow:none;cursor:default;break-inside:avoid;grid-template-columns:1fr auto;align-items:center;overflow:hidden}
  .qr-print .qrl__l small,.qr-print .qrl__l em{white-space:nowrap;overflow:hidden}
  .qr-print .qrl__l img{height:3.6mm;margin-bottom:1.6mm}
  .qr-print .qrl__l b{font-size:5mm}
  .qr-print .qrl__l small{font-size:2.2mm;margin-top:1.2mm}
  .qr-print .qrl__l em{font-size:1.8mm;margin-top:1.6mm}
  .qr-print .qrl__q{width:20mm;height:20mm}
  .qr-print .qrl__site{left:2.5mm;bottom:.8mm;font-size:1.9mm}
  .qr-print--l .qrl{padding:3mm 3.5mm 3.5mm}
  .qr-print--l .qrl__l img{height:5mm}.qr-print--l .qrl__l b{font-size:7mm}.qr-print--l .qrl__l small{font-size:3mm}.qr-print--l .qrl__l em{font-size:2.6mm}
  .qr-print--l .qrl__q{width:30mm;height:30mm}.qr-print--l .qrl__site{font-size:2.4mm}
}

/* ---- akıllı arama ---------------------------------------------------- */
.qchip{display:inline-block;background:var(--ink);color:#fff;font-size:11px;letter-spacing:.08em;font-weight:600;padding:4px 10px;border-radius:999px;margin:0 6px 6px 0;vertical-align:middle}
.qchip--x{background:transparent;color:var(--muted);border:1px dashed var(--line);text-decoration:line-through;font-weight:500}
.qlead{font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);margin-right:8px;vertical-align:middle}
.qnote{color:var(--muted-2);font-size:13px}
.search-suggest__chips{padding:8px 10px 4px;border-bottom:1px solid var(--line-2);margin-bottom:4px}
.search-suggest__chips small{display:block;color:var(--muted-2);font-size:11px;margin-top:2px}
.search-suggest__all{display:block!important;text-align:center;font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:600;color:var(--red);border-top:1px solid var(--line-2);margin-top:4px;padding:10px!important}

/* ---- bayi talep formu --------------------------------------------- */
.order-badge{display:inline-block;background:var(--red);color:#fff;font-size:10px;font-weight:600;border-radius:999px;padding:1px 7px;margin-left:6px;vertical-align:middle}
.order-add{position:relative}.order-add.done{background:#166534}
.order-note{font-size:13px;color:var(--ink-2);margin-top:10px}.order-note a{color:var(--red);text-decoration:underline}
.order__sec{border:1px solid var(--line);border-radius:6px;padding:22px 24px;margin:0 0 18px}
.order__sec h3{font-size:12px;letter-spacing:.24em;text-transform:uppercase;color:var(--red);font-weight:600;margin:0 0 12px}
.order__hint{font-size:13px;color:var(--muted-2);margin:0 0 12px}
.order__search{position:relative;max-width:520px;margin-bottom:16px}
.order__search input{width:100%;border:1px solid var(--line);border-radius:var(--radius);padding:12px 14px;font:inherit;font-size:14px}
.order__suggest{position:absolute;top:100%;left:0;right:0;z-index:20;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);border-radius:var(--radius);display:flex;flex-direction:column}
.order__suggest:empty{display:none}
.order__suggest button{display:flex;align-items:center;gap:12px;border:0;background:#fff;padding:8px 12px;text-align:left;font:inherit;color:var(--ink)}
.order__suggest button:hover{background:var(--bg-soft)}
.order__suggest img{width:64px;height:auto}.order__suggest b{display:block;font-size:14px}.order__suggest small{color:var(--muted-2);font-size:12px}.order__suggest em{margin-left:auto;font-style:normal;color:var(--red);font-size:12px;font-weight:600;letter-spacing:.1em}
.order__table{width:100%;border-collapse:collapse;font-size:14px}
.order__table th{text-align:left;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);font-weight:500;padding:0 10px 8px 0;border-bottom:1px solid var(--line)}
.order__table td{padding:10px 10px 10px 0;border-bottom:1px solid var(--line-2);vertical-align:middle}
.order__table img{width:84px;height:auto}.order__table b{display:block}.order__table small{color:var(--muted-2);font-size:12px}
.order__table select,.order__table input{border:1px solid var(--line);border-radius:var(--radius);padding:8px 10px;font:inherit;font-size:13px;max-width:260px}
.order__table input[type=number]{width:74px}
.order__rm{border:0;background:transparent;color:var(--muted);font-size:14px;padding:6px}.order__rm:hover{color:var(--red)}
.order__total{margin:12px 0 0;font-size:14px;color:var(--ink-2)}
.order__form{display:grid;grid-template-columns:1fr 1fr;gap:12px 18px}
.order__form label{display:flex;flex-direction:column;gap:6px;font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted-2);font-weight:500}
.order__form input,.order__form textarea{border:1px solid var(--line);border-radius:var(--radius);padding:11px 12px;font:inherit;font-size:14px;letter-spacing:0;text-transform:none;color:var(--ink)}
.order__wide{grid-column:1/-1}
.order__btns{display:flex;gap:10px;flex-wrap:wrap}
.order__msg{margin:14px 0 0;font-size:14px;min-height:1em}.order__msg.ok{color:#166534}.order__msg.err{color:var(--red)}
.order__foot{font-size:12px;color:var(--muted-2);margin-top:18px}
@media (max-width:700px){.order__form{grid-template-columns:1fr}.order__table th:first-child,.order__table td:first-child{display:none}.order__table select{max-width:150px}}

/* ---- satış noktaları: harita, yol tarifi, yakınımdakiler ---------- */
.dealers-ctx{display:flex;align-items:center;gap:18px;border:1px solid var(--line);border-radius:6px;padding:12px 18px;margin:0 0 22px;background:#FAFAFA}
.dealers-ctx img{width:120px;height:auto}.dealers-ctx .eyebrow{margin:0 0 4px}.dealers-ctx b{display:block;font-size:17px}.dealers-ctx small{color:var(--muted-2);font-size:12px}.dealers-ctx a{color:var(--red);text-decoration:underline}
.dealers-search .btn--ghost{padding:12px 16px;gap:8px}
.dealers-districts{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
.dealers-body--map{display:grid;grid-template-columns:1.1fr .9fr;gap:24px;align-items:start}
.dealers-body--map .dealer-grid{grid-template-columns:1fr 1fr}
.dealers-frame{position:sticky;top:90px}
.dealers-frame__in{border:1px solid var(--line);border-radius:6px;overflow:hidden;background:var(--bg-soft)}
.dealers-frame iframe{display:block;width:100%;height:440px;border:0}
.dealers-frame__label{margin:0;padding:10px 14px;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2);font-weight:600;border-top:1px solid var(--line)}
.dealer.active{border-color:var(--red);box-shadow:0 0 0 2px var(--red) inset}
.dealer__dist{float:right;font-size:12px;font-weight:600;color:var(--red);background:#FEE2E2;padding:3px 9px;border-radius:999px}
.dealers-demo{font-size:12px;color:var(--muted-2);margin-top:22px}
.dealers-demo:empty{display:none}
@media (max-width:1000px){.dealers-body--map{grid-template-columns:1fr}.dealers-frame{position:static}.dealers-frame iframe{height:320px}.dealers-body--map .dealer-grid{grid-template-columns:1fr 1fr}}
@media (max-width:640px){.dealers-body--map .dealer-grid{grid-template-columns:1fr}.dealers-ctx img{width:90px}}

/* ---- dil anahtarı ------------------------------------------------- */
.lang{display:inline-flex;align-items:center;gap:6px;font-size:12px;letter-spacing:.14em;font-weight:600;color:var(--muted)}
.lang a{color:var(--muted);padding:4px 2px}.lang a.on{color:var(--ink);border-bottom:2px solid var(--red)}
.lang--nav{margin:0 6px 0 4px}
.lang--footer{margin-left:auto}.lang--footer a{color:#C9CDD2}.lang--footer a.on{color:#fff}
@media (max-width:1024px){.lang--nav{padding:10px 11px}}

/* ---- Instagram bandı ------------------------------------------------ */
.ig__grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}
.ig__item{position:relative;display:block;aspect-ratio:1;overflow:hidden;border-radius:4px;background:var(--line)}
.ig__item img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.ig__item:hover img{transform:scale(1.05)}
.ig__hover{position:absolute;inset:0;display:grid;place-items:center;background:rgba(17,24,39,.45);color:#fff;opacity:0;transition:.25s}
.ig__hover svg{width:30px;height:30px}.ig__item:hover .ig__hover{opacity:1}
.ig__video{position:absolute;top:10px;right:10px;width:26px;height:26px;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;display:grid;place-items:center}.ig__video svg{width:14px;height:14px}
@media (max-width:900px){.ig__grid{grid-template-columns:repeat(3,1fr)}}

/* ---- yüz şekli rehberi ----------------------------------------------- */
.face__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;max-width:820px;margin:0 auto}
.face__item{display:flex;flex-direction:column;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:6px;padding:18px 10px 14px;color:var(--ink);transition:.15s}
.face__item svg{width:70px;height:72px}.face__item span{font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:600}
.face__item:hover{border-color:var(--ink);transform:translateY(-2px);box-shadow:var(--shadow)}
.face__item.on{border-color:var(--red);box-shadow:0 0 0 2px var(--red) inset;color:var(--red)}
.face__result:empty{display:none}
.face__box{display:grid;grid-template-columns:.9fr 1.1fr;gap:34px;align-items:start;margin-top:34px;border-top:1px solid var(--line);padding-top:30px}
.face__text h3{font-size:22px;font-weight:600;margin-bottom:10px}.face__text p{color:var(--ink-2);font-size:14px;line-height:1.7}
.face__shapes{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0 22px}
.face__shape{display:flex;flex-direction:column;align-items:center;gap:4px;border:1px solid var(--line);border-radius:6px;padding:8px 12px;font-size:11px;letter-spacing:.1em;text-transform:uppercase}
.face__shape svg{width:70px;height:40px}
.face__models .grid{grid-template-columns:repeat(2,1fr);gap:12px}
.fshape{display:inline-block;width:34px;height:20px;color:var(--ink-2)}.fshape svg{width:34px;height:20px}
@media (max-width:900px){.face__grid{grid-template-columns:repeat(2,1fr)}.face__box{grid-template-columns:1fr}.face__models .grid{grid-template-columns:repeat(2,1fr)}}

/* ---- ölçü aracı ------------------------------------------------------ */
.sizetool{border:1px solid var(--line);border-radius:6px;padding:26px 28px;margin:0 0 34px;background:#FAFAFA}
.sizetool h2{font-size:22px;font-weight:600;margin:0 0 8px}.sizetool__hint{font-size:14px;color:var(--ink-2);margin:0 0 16px}
.sizetool__form{display:flex;gap:10px;flex-wrap:wrap}
.sizetool__form input{flex:1;min-width:200px;max-width:320px;border:1px solid var(--line);border-radius:var(--radius);padding:13px 16px;font:inherit;font-size:18px;letter-spacing:.08em}
.sizetool__out{margin-top:20px}.sizetool__out:empty{display:none}
.sizetool__sum{font-size:14px;color:var(--ink-2);margin:0 0 16px}.sizetool__sum b{color:var(--ink);font-size:18px}
.guide-size{display:flex;gap:8px;flex-wrap:wrap;margin-top:28px;max-width:460px}
.guide-size input{flex:1;min-width:180px;border:1px solid rgba(255,255,255,.35);background:rgba(255,255,255,.08);color:#fff;border-radius:var(--radius);padding:12px 14px;font:inherit;font-size:15px}
.guide-size input::placeholder{color:#C9CDD2}

/* ---- favoriler --------------------------------------------------------- */
.fav{position:absolute;top:10px;right:10px;z-index:3;width:34px;height:34px;border-radius:50%;border:1px solid var(--line);background:rgba(255,255,255,.92);display:grid;place-items:center;color:var(--muted-2);transition:.15s}
.fav svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2}
.fav:hover{color:var(--red);border-color:var(--red)}
.fav.on{color:var(--red);border-color:var(--red)}.fav.on svg{fill:var(--red)}
.card__img{position:relative}
.fav--text{position:static;width:auto;height:auto;border-radius:var(--radius);display:inline-flex;gap:10px;padding:14px 26px}
.fav--text svg{width:16px;height:16px}
.nav__fav{display:inline-flex;align-items:center;gap:4px;padding:10px 8px!important;position:relative;color:var(--ink)}
.nav__fav svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2}
.nav__favn{font-size:10px;font-weight:600;background:var(--red);color:#fff;border-radius:999px;padding:1px 6px;line-height:1.4}
.fav-share,.fav-wa{color:var(--red);text-decoration:underline}

/* ---- sanal deneme ------------------------------------------------------ */
.tryon-btn{margin-top:14px;width:100%;gap:10px}.tryon-btn svg{width:18px;height:18px}
.tryon{position:fixed;inset:0;z-index:110;background:rgba(17,24,39,.72);display:none;align-items:center;justify-content:center;padding:20px}
.tryon.open{display:flex}
.tryon__box{position:relative;width:min(1100px,100%);max-height:100%;background:#fff;border-radius:10px;overflow:hidden;display:grid;grid-template-columns:1.3fr .8fr;box-shadow:0 30px 80px rgba(0,0,0,.45)}
.tryon__x{position:absolute;top:12px;right:12px;z-index:3;width:38px;height:38px;border:0;border-radius:50%;background:rgba(255,255,255,.9);color:var(--ink);font-size:16px}
.tryon__stage{position:relative;background:#111;min-height:420px;display:grid;place-items:center}
.tryon__stage video{display:none}
.tryon__stage canvas{width:100%;height:100%;max-height:78vh;object-fit:contain;display:block}
.tryon__status{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);background:rgba(0,0,0,.6);color:#fff;font-size:13px;padding:8px 14px;border-radius:999px;white-space:nowrap;max-width:90%;overflow:hidden;text-overflow:ellipsis}
.tryon__panel{padding:44px 30px 26px;display:flex;flex-direction:column;gap:14px;overflow:auto}
.tryon__title{font-size:24px;font-weight:600;margin:0}.tryon__meta{color:var(--muted-2);font-size:13px;margin:0}
.tryon__colors{display:flex;flex-wrap:wrap;gap:8px}
.tryon__color{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:#fff;border-radius:999px;padding:6px 12px 6px 8px;font-size:12px;font-weight:600;color:var(--ink)}
.tryon__color.on{border-color:var(--red);box-shadow:0 0 0 1px var(--red)}
.tryon__color .sw{width:16px;height:16px}
.tryon__adj{display:flex;align-items:center;gap:10px;font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted-2)}
.tryon__adj input{flex:1;accent-color:var(--red)}.tryon__adj span{font-weight:600;color:var(--ink);min-width:44px;letter-spacing:0}
.tryon__btns{display:flex;flex-wrap:wrap;gap:8px}.tryon__btns .btn{padding:12px 16px;cursor:pointer}
.tryon__note{font-size:12px;color:var(--muted-2);line-height:1.6;margin:auto 0 0}
@media (max-width:900px){.tryon{padding:0}.tryon__box{grid-template-columns:1fr;grid-template-rows:auto 1fr;height:100%;border-radius:0}.tryon__stage{min-height:0}.tryon__stage canvas{max-height:52vh}.tryon__panel{padding:18px 18px 16px;gap:10px}.tryon__title{font-size:19px}}

